// pxl-tool/spec/cmd.rs

//! The kernel's machine and its protocol with the shell, generated by
//! xpute's generator where each one's `gen` says.

use xpute_tool::spec::cmd::protocol_outputs;
use xpute_tool::spec::machine;

use super::Output;
use crate::root;

pub fn outputs() -> Result<Vec<Output>, String> {
    let mut out = machine::outputs(&root(), "rust/client/kernel/machine.json")?;
    out.extend(protocol_outputs(
        &root(),
        &["rust/client/kernel/shell.json"],
    )?);
    Ok(out
        .into_iter()
        .map(|o| Output::new(&o.path, o.text))
        .collect())
}
